// Generated by cockpit/build.mjs from cockpit/src. Do not edit.
//
// These are the cockpit's pure functions, tested in node — see cockpit/README.md. They are
// globals here because the page is one classic script; they are modules there because a
// function that cannot be imported cannot be tested except by reimplementing it, and a
// reimplementation agrees with the code right up until one of them changes.

// ── ago.mjs ──
// How long ago, in the words the board uses.
//
// **Formatted here rather than on the server**, and the reason is that the stream stopped re-sending
// a box that only got older. Change detection ignores the clock-derived fields — a box's age moves
// every second whether or not anything happened to it, and leaving it in made every box change on
// every tick — so a server-formatted string would freeze between real changes and a fleet that had
// been quiet for ten minutes would say "2m ago" for ever.
//
// The server sends `age_secs`: the age **at the moment of the observation**. The client knows when
// it received it. So the age is that plus the time since, recomputed on a timer that costs nothing
// and needs no traffic at all.
//
// One formatter, in one language. It was `util::ago` in Rust; two that can disagree is the shape
// §11.7 exists to end, and this is the one the person reads.

// `secs` may be null — `age_secs` is absent when a box's `lastSeen` is unparseable or missing.
// "We do not know" and "just now" are different things and this is the field that says so, so it
// renders as `?` exactly as the server's did, and never as `0s ago`.
function ago(secs) {
  if (secs === null || secs === undefined || Number.isNaN(secs)) return "?";
  const s = Math.max(0, Math.floor(secs));
  if (s < 60) return `${s}s ago`;
  if (s < 3600) return `${Math.floor(s / 60)}m ago`;
  if (s < 86400) return `${Math.floor(s / 3600)}h ago`;
  return `${Math.floor(s / 86400)}d ago`;
}

// A row's age now: what it was when it was observed, plus how long ago that was.
//
// `sinceMs` is how long the row has been held, in milliseconds. Clamped at zero, because a clock
// that steps backwards should make a row look freshly seen rather than make it say `-3s ago`.
function ageNow(secs, sinceMs) {
  if (secs === null || secs === undefined || Number.isNaN(secs)) return "?";
  return ago(secs + Math.max(0, Math.floor((sinceMs || 0) / 1000)));
}

// ── filter.mjs ──
// The board's filter, as a function of what it is given.
//
// `foreign:` is the one term that changes WHICH boxes are eligible rather than narrowing them. A
// sandbox skein did not place is not on the board's tick at all any more — it is fetched when
// somebody asks — so the eligible pool is passed in rather than filtered out of the board's rows.

const FOREIGN_TERM = "foreign:";
const wantsForeign = q => (q || "").includes(FOREIGN_TERM);
const withoutForeignTerm = q => (q || "").split(FOREIGN_TERM).join(" ").trim();

// Does this row match the words typed? Every word must appear somewhere, so adding one narrows.
function matchesFilter(b, q) {
  if (!q) return true;
  const hay = `${b.name} ${b.branch || ""} ${b.repo || ""} ${b.headline || ""}`.toLowerCase();
  return q.split(/\s+/).filter(Boolean).every(t => hay.includes(t));
}

// Which rows the board draws, for a fleet, a filter, and the foreign rows if any have been fetched.
//
// **`foreign` is an argument.** It used to be module state the function reached out for, which is
// exactly what made this untestable — a pure function is one whose inputs are all in front of you.
//
// Eligibility first, then the text match over what is left, because `foreign:` answers "which boxes"
// and the rest answers "which of those".
function boardRows(all, rawFilter, foreign) {
  const q = (rawFilter || "").trim().toLowerCase();
  const pool = wantsForeign(q) ? (foreign || []) : (all || []);
  const eligible = pool.filter(b => (wantsForeign(q) ? b.foreign : !b.foreign));
  const text = withoutForeignTerm(q);
  return text ? eligible.filter(b => matchesFilter(b, text)) : eligible;
}

// ── groups.mjs ──
// Which group a box's state belongs to, and what "owed to you" means.
//
// One place, because it was written out three times and they disagreed: the tab title and the
// needs-you navigation counted `waiting` and both voice paths did not — so the title said "3 need
// you" while the mouth stayed shut, and "read what needs me" answered "nothing needs you" with boxes
// visibly waiting on screen.
const GROUPS = [
  { key: "error", label: "error", match: s => s === "error" },
  { key: "attn", label: "needs you", match: s => ["needs-input", "needs-decision", "blocked"].includes(s) },
  { key: "waiting", label: "waiting", match: s => s === "waiting" },
  { key: "done", label: "done", match: s => s === "done" },
  { key: "working", label: "working", match: s => ["working", "running", "live", "compacting"].includes(s) },
  { key: "ended", label: "ended", match: s => s === "ended" },
  { key: "idle", label: "idle", match: s => s === "idle" },
  { key: "stale", label: "stale", match: s => s === "stale" || s === "unknown" },
];

// An unrecognised state falls to the last group rather than to nothing: a box whose state this page
// has never heard of is a box that is not talking, which is what `stale` means.
const groupOf = s => (GROUPS.find(g => g.match(s)) || GROUPS[GROUPS.length - 1]).key;

// `waiting` is a box that ended its turn and wants your next instruction, which is the most ordinary
// way a box needs you there is.
const NEEDS_YOU = ["error", "attn", "waiting"];

const owedIn = list => list.filter(b => NEEDS_YOU.includes(groupOf(b.state)));

const labelOf = s =>
  ["needs-input", "needs-decision", "blocked"].includes(s) ? "decision" : s === "live" ? "active" : s;

// ── sizes.mjs ──
// Sizes, in the units a person reads.
//
// Two of them, because the server sends bytes for memory and mebibytes for disk, and a single
// formatter taking "a number" is one that eventually gets handed the wrong one.

// Bytes.
const fmtGB = b =>
  b >= 1073741824 ? `${(b / 1073741824).toFixed(1)}G` : `${Math.round(b / 1048576)}M`;

// Mebibytes.
const fmtGb = mb => (mb >= 1024 ? `${(mb / 1024).toFixed(1)}G` : `${mb}M`);

